import React, { useState } from "react";
import { siteConfig } from "@/config/site";
import {
  Menu,
  X,
  MapPin,
  Calendar,
  Users,
  Search,
  ChevronDown,
  Shield,
  MessageCircle,
  Building2,
  Headphones,
  Star,
  CalendarX,
  Zap,
  Tag,
  Plane,
  Eye,
} from "lucide-react";

const iconMap: Record<string, React.ReactNode> = {
  Shield: <Shield className="w-6 h-6" />,
  MessageCircle: <MessageCircle className="w-6 h-6" />,
  Building2: <Building2 className="w-6 h-6" />,
  Headphones: <Headphones className="w-6 h-6" />,
  Star: <Star className="w-6 h-6" />,
  CalendarX: <CalendarX className="w-6 h-6" />,
  Zap: <Zap className="w-6 h-6" />,
  Tag: <Tag className="w-6 h-6" />,
  Plane: <Plane className="w-6 h-6" />,
  Eye: <Eye className="w-6 h-6" />,
  MapPin: <MapPin className="w-6 h-6" />,
};

export function getIcon(name: string) {
  return iconMap[name] || <Shield className="w-6 h-6" />;
}

interface LayoutProps {
  children: React.ReactNode;
  currentPage: string;
}

export function Layout({ children, currentPage }: LayoutProps) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const isActive = (item: (typeof siteConfig.nav)[0]) => {
    return item.activeOn.includes(currentPage);
  };

  return (
    <div className="min-h-screen bg-white">
      {/* Header */}
      <header className="sticky top-0 z-50 bg-[#003B95] text-white shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            {/* Logo */}
            <a href="index.html" className="flex items-center gap-2">
              <div className="w-8 h-8 bg-[#FFB700] rounded-lg flex items-center justify-center">
                <MapPin className="w-5 h-5 text-[#003B95]" />
              </div>
              <span className="text-xl font-bold tracking-tight">
                {siteConfig.name}
              </span>
            </a>

            {/* Desktop Nav */}
            <nav className="hidden lg:flex items-center gap-1">
              {siteConfig.nav.map((item) => (
                <a
                  key={item.label}
                  href={item.href}
                  className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                    isActive(item)
                      ? "bg-white/15 text-white"
                      : "text-white/80 hover:text-white hover:bg-white/10"
                  }`}
                >
                  {item.label}
                </a>
              ))}
            </nav>

            {/* Right side */}
            <div className="flex items-center gap-3">
              <button className="hidden sm:flex items-center gap-2 px-4 py-2 rounded-md bg-white text-[#003B95] text-sm font-semibold hover:bg-white/90 transition-colors">
                Sign in
              </button>
              <button
                className="lg:hidden p-2 rounded-md hover:bg-white/10"
                onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              >
                {mobileMenuOpen ? (
                  <X className="w-6 h-6" />
                ) : (
