function RatingBadge({ rating, label }: { rating: number; label: string }) {
  let colorClass = "bg-gray-100 text-gray-700";
  if (rating >= 9) colorClass = "bg-emerald-100 text-emerald-700";
  else if (rating >= 8) colorClass = "bg-green-100 text-green-700";
  else if (rating >= 7) colorClass = "bg-blue-100 text-blue-700";
  else if (rating >= 6) colorClass = "bg-yellow-100 text-yellow-700";

  return (
    <div className="flex items-center gap-2">
      <span
        className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-semibold ${colorClass}`}
      >
        {rating}
      </span>
      <span className="text-sm text-gray-600">{label}</span>
    </div>
  );
}

